"""Read-only parameter/logit/readout diagnostics on the completed TTA seal."""
from common import *
import math,argparse
G=D/'published_TTA'
def run():
 import torch,numpy as np
 torch.set_num_threads(1);validate('published_TTA');seal=read(G/'sealed.json');audit=read(G/'reporting_receipt.json');assert audit['score_sha256']==sha(G/'score_receipt.json');diag={}
 for ds,files in seal['files'].items():
  stats={m:dict(queries=0,nonzero_parameter_delta_queries=0,changed_logit_queries=0,changed_native_intervals=0,changed_jointMAP_intervals=0,max_logit_abs_change=0.,parameter_delta_min=None,parameter_delta_max=0.,SAR_empty_first_filter_iterations=0,SAR_empty_second_after_first_filter_iterations=0)for m in ['Tent','SAR']};individual=[]
  for i,(key,e)in enumerate(files.items(),1):
   assert sha(D/e['logits_path'])==e['logits_sha256'];cp=e['parent']['capture'];assert sha(cp)==e['parent']['capture_sha256'];c=torch.load(cp,map_location='cpu',weights_only=False,mmap=True);a=torch.load(D/e['logits_path'],map_location='cpu',weights_only=False,mmap=True)
   with np.load(D/e['path'])as z,np.load(current_MAP(ds,key)[0])as control:
    for m in ['Tent','SAR']:
     t=e['traces'][m];v=stats[m];v['queries']+=1;delta=t['parameter_delta'];v['nonzero_parameter_delta_queries']+=int(delta>0);v['parameter_delta_min']=delta if v['parameter_delta_min']is None else min(v['parameter_delta_min'],delta);v['parameter_delta_max']=max(v['parameter_delta_max'],delta);change=max(float((x-y).abs().max())for x,y in zip(a['adapted_logits'][m],c['native_logits']));v['changed_logit_queries']+=int(change>0);v['max_logit_abs_change']=max(v['max_logit_abs_change'],change);cn=not np.array_equal(z[m+'Native_interval'],z['Source_interval']);cj=not np.array_equal(z[m+'JointMAP_interval'],control['SourceJointMAP_interval']);v['changed_native_intervals']+=int(cn);v['changed_jointMAP_intervals']+=int(cj)
     if m=='SAR':
      margin=t['trial']['margin_fraction']*math.log(max(x.shape[1]for x in a['adapted_logits'][m]))
      for step in t['steps']:
       ent1=np.asarray(step['forwards'][0]['entropy']);ent2=np.asarray(step['forwards'][1]['entropy']);v['SAR_empty_first_filter_iterations']+=int(not(ent1<margin).any());v['SAR_empty_second_after_first_filter_iterations']+=int(not((ent1<margin)&(ent2<margin)).any())
     individual.append(dict(query=f'Q{i:03}',method=m,parameter_delta=delta,max_logit_abs_change=change,native_interval_changed=cn,jointMAP_interval_changed=cj,reset_exact=t['reset_exact'],decoder_calls=t['decoder_calls'],adaptation_seconds=t['seconds']))
  diag[ds]=stats;folder=P/'published_TTA'/ds;atomic(folder/'adaptation_diagnostics.json',dict(statistics=stats,queries=individual,scope='Read-only exact savedlogits/parent/native-and-jointMAP intervals, no model/GT. EmptySARfilters are original official algorithm behavior, no Sourcefallback substituted.',audit_sha256=sha(G/'reporting_receipt.json')));r=read(folder/'report.json');s=f"# Official Tent/SAR STVG adapters: {ds}\n\n**Complete scored and replay-audited fixed panel:**128queries/128parents. Both methods use the previously selected development configurations, genuine episodic original temporal-decoder LayerNorm-affine updates, exact cached native decoder contexts and Source boxes, five iterations, and pinned unmodified official algorithm source. No new Source/expert/RGB is collected. Original queryreset/native-logit reset and all512configuration readouts were audited. This is a disclosed STVG task adapter, not canonical BN/fullnetwork/continual adaptation or a universal TTA ranking.\n\n| Configuration | tIoU % | vIoU % | Severe t/v/union vs native Source |\n|---|---:|---:|---|\n"
  for name,v in r['means'].items():
   z=r['severe_vs_Source'][name];s+=f"| {name} | {100*v['t']:.6f} | {100*v['v']:.6f} | {z['t']}/{z['v']}/{z['union']} |\n"
  s+='\nBoth adapted native intervals are unchanged on every query. The separately computed same-logit joint-MAP outputs are also unchanged from SourceJointMAP. This is a zero change in decoded accuracy under these frozen settings, not evidence that no optimization was executed.\n\n| Method | Nonzero final parameter changes | Changed saved logits | Changed native intervals | Changed jointMAP intervals |\n|---|---:|---:|---:|---:|\n'
  for m,v in stats.items():s+=f"| {m} | {v['nonzero_parameter_delta_queries']}/128 | {v['changed_logit_queries']}/128 | {v['changed_native_intervals']}/128 | {v['changed_jointMAP_intervals']}/128 |\n"
  s+='\nExact saved parameter norms, logit magnitudes, per-query cost/reset diagnostics and raw reliability-filter counts are in [adaptation diagnostics](adaptation_diagnostics.json). SAR can leave no final parameter change when the official reliable-entropy filters admit no entries; no fallback output is inserted by this study. `SAR_empty_second_after_first_filter_iterations` uses the original first-filter membership intersected with the second-pass threshold, rather than treating the recorded raw second-pass count as its actual retained set. All original traces remain private and sealed.\n\n| Signed comparison | Δt pp [95% CI] | Δv pp [95% CI] |\n|---|---:|---:|\n'
  for key,v in r['paired'].items():
   def fmt(x):return f"{x['mean']:+.6f} [{x['CI95'][0]:.6f}, {x['CI95'][1]:.6f}]"
   s+=f"| {key} | {fmt(v['t'])} | {fmt(v['v'])} |\n"
  s+='\nAll comparisons are on the same previously exposed128-parent panel, not the complete target set. Pointwise parent-cluster intervals are not familywise guarantees. In Vid, the FullMAP−native-source/TTA vIoU interval crosses zero; do not claim a significant advantage in both domains. FullMAP uses eight expert observations and zero optimizer steps; Tent/SAR use zero expert observations and five iterations. These are different budgets, explicitly disclosed.\n\nAll signed per-query metrics/severe losses/rescues/duration groups and observed/unobserved tradeoffs are retained in report.json, all_signed.tsv and all_signed_severe_timegroups.tsv. Native Source uses per-offset MAP plus physical hull; SourceJointMAP isolates readout effects. FullMAP is the already-completed current MAP configuration on the identical cohort, not a newly selected model.\n\n'
  s+=f"Actual cached-context adaptation costs: {json.dumps(audit['costs'][ds])}. These include real decoder forward/backward and optimizer work, but exclude inherited Source/context acquisition; they are not complete deployment timings or free acquisition. Actual deployment Source/currentFull timings are reported independently. Whole256 predictions were sealed before independent official scoring (1,280dense checks), then768prediction/logit/receipt SHA checks, all adapted native/joint readout replays, allmeans and episodic resets passed. Original parameter/evidence settings are unchanged, with no new sweep based on these results."
  (folder/'ANALYSIS.md').write_text(s)
 atomic(G/'analysis_export_receipt.json',dict(status='complete_verified',diagnostics=diag,code_sha256=sha(Path(__file__)),audit_sha256=sha(G/'reporting_receipt.json'),new_model=0,new_GT_scoring=0));print(json.dumps(diag,indent=2))
if __name__=='__main__':run()
